    "cmd": "python -c \"content = '''\\\"\\\"\\\"\\nGenerate synthetic sensor panel timeseries data for structural health analysis.\\n\\\"\\\"\\\"\\nimport pandas as pd\\nimport numpy as np\\nfrom datetime import datetime\\n\\nnp.random.seed(42)\\n\\nassets = ['PUMP-001', 'PUMP-002', 'PUMP-003', 'MOTOR-001', 'MOTOR-002', 'FAN-001', 'FAN-002', 'COMP-001']\\nzones = ['Zone-A', 'Zone-B', 'Zone-C']\\nasset_zone_map = {\\n    'PUMP-001': 'Zone-A', 'PUMP-002': 'Zone-A', 'PUMP-003': 'Zone-B',\\n    'MOTOR-001': 'Zone-B', 'MOTOR-002': 'Zone-C',\\n    'FAN-001': 'Zone-C', 'FAN-002': 'Zone-A',\\n    'COMP-001': 'Zone-B'\\n}\\n\\nasset_params = {\\n    'PUMP': {'base_vibration': 2.5, 'base_temp': 55, 'base_rpm': 1750, 'base_load': 70},\\n    'MOTOR': {'base_vibration': 1.8, 'base_temp': 65, 'base_rpm': 1800, 'base_load': 75},\\n    'FAN': {'base_vibration': 3.2, 'base_temp': 45, 'base_rpm': 1200, 'base_load': 60},\\n    'COMP': {'base_vibration': 4.0, 'base_temp': 70, 'base_rpm': 3000, 'base_load': 85}\\n}\\n\\nstart_date = datetime(2025, 10, 1, 0, 0, 0)\\nend_date = datetime(2025, 10, 31, 23, 0, 0)\\ntimestamps = pd.date_range(start=start_date, end=end_date, freq='H')\\ndegradation_assets = ['PUMP-002', 'COMP-001']\\ntrend_start_day = 15\\n\\nrows = []\\nfor ts in timestamps:\\n    day_of_month = ts.day\\n    hour_of_day = ts.hour\\n    for asset_id in assets:\\n        zone = asset_zone_map[asset_id]\\n        asset_type = asset_id.split('-')[0]\\n        params = asset_params[asset_type]\\n        temp_cycle = 5 * np.sin((hour_of_day - 6) * np.pi / 12)\\n        load_factor = 1.1 if 8 <= hour_of_day <= 18 else 0.85\\n        vibration_noise = np.random.normal(0, params['base_vibration'] * 0.15)\\n        temp_noise = np.random.normal(0, 3)\\n        rpm_noise = np.random.normal(0, params['base_rpm'] * 0.02)\\n        load_noise = np.random.normal(0, 5)\\n        if asset_id in degradation_assets and day_of_month > trend_start_day:\\n            degradation_factor = 1 + (day_of_month - trend_start_day) * 0.08\\n            vibration_noise += params['base_vibration'] * 0.5 * (degradation_factor - 1)\\n            temp_noise += 2 * (degradation_factor - 1)\\n        vibration_rms = max(0.1, params['base_vibration'] * load_factor + vibration_noise)\\n        peak_accel = vibration_rms * np.random.uniform(2.5, 4.0)\\n        bearing_temp = params['base_temp'] + temp_cycle + temp_noise\\n        rpm = max(100, params['base_rpm'] * load_factor + rpm_noise)\\n        load_pct = max(10, min(100, params['base_load'] * load_factor + load_noise))\\n        quality_flag = 'GOOD' if np.random.random() < 0.95 else ('WARNING' if np.random.random() < 0.7 else 'ERROR')\\n        rows.append({'timestamp_utc': ts.strftime('%Y-%m-%d %H:%M:%S'), 'asset_id': asset_id, 'zone': zone, 'vibration_rms_mm_s': round(vibration_rms, 3), 'peak_accel_g': round(peak_accel, 3), 'bearing_temp_c': round(bearing_temp, 1), 'rpm': round(rpm, 0), 'load_pct': round(load_pct, 1), 'quality_flag': quality_flag})\\n\\ndf = pd.DataFrame(rows)\\ndf.to_csv('data/sensor_panel_timeseries.csv', index=False)\\nprint(f'Generated {len(df)} rows')\\n'''\\nwith open('code/generate_data.py', 'w') as f:\\n    f.write(content)\\nprint('File written')\""
